const emails = $input.all();
const flagged = [];
for (const { json: m } of emails) {
  const subject = (m.subject || '').toLowerCase();
  const body = (m.body || '').toLowerCase().slice(0, 3000);
  const from = (m.from_addr || '').toLowerCase();
  const flags = [];
  if (/(urgent|verify your account|suspicious login|password expired|unusual activity|wire transfer|gift card)/.test(subject + ' ' + body)) flags.push('social-engineering');
  if (/http|https:\/\//.test(body)) flags.push('has-link');
  if ((m.att_count || 0) > 2) flags.push('many-attachments');
  if (/noreply|no-reply|security@|support@/.test(from) && /password|login|account/.test(subject)) flags.push('spoofed-sender');
  if (flags.length) flagged.push({ json: { id: m.id, from_addr: m.from_addr, subject: m.subject, flags, risk: flags.length > 1 ? 'high' : 'medium', flagged: true } });
}
return flagged.length ? flagged : [{ json: { id: 0, flagged: false } }];

const flagged = $input.all().filter(i => i.json.flagged === true);
const scanned = $('Bot 1 - Load Emails').all().length;
return [{ json: { emails_scanned: scanned, emails_flagged: flagged.length, flagged_ids: flagged.map(i => i.json.id) } }];

const run = async () => {
  const accounts = $input.all();
  const HIBP_KEY = $env.HIBP_API_KEY || '';
  const results = [];
  const seen = new Set();
  const check = async (path) => {
    try {
      const res = await fetch('https://haveibeenpwned.com/api/v3/' + path, {
        headers: { 'hibp-api-key': HIBP_KEY, 'user-agent': 'prism-security-scanner/1.0' }
      });
      if (res.status === 404) return null;
      if (res.status === 429) { await new Promise(r => setTimeout(r, 5000)); return check(path); }
      if (!res.ok) return null;
      return await res.json();
    } catch (e) { return null; }
  };
  for (const { json: a } of accounts) {
    const email = (a.email || '').trim().toLowerCase();
    if (!email || seen.has(email)) continue;
    seen.add(email);
    const breaches = [], pastes = [];
    const b = await check('breachedaccount/' + encodeURIComponent(email));
    if (Array.isArray(b)) b.forEach(x => breaches.push(x.Name || x.Title));
    const p = await check('pasteaccount/' + encodeURIComponent(email));
    if (Array.isArray(p)) p.forEach(x => pastes.push((x.Source || '') + ':' + (x.Id || '')));
    results.push({ json: { account_id: a.id, email, provider: a.provider, breaches, breach_count: breaches.length, pastes, paste_count: pastes.length, leaked: breaches.length > 0 || pastes.length > 0 } });
  }
  return results;
};
return run();

const run = async () => {
  const items = $input.all();
  const out = [];
  const rand = () => Math.random().toString(36).slice(2, 8);
  for (const { json: a } of items) {
    if (a.leaked) {
      for (let i = 0; i < 2; i++) {
        out.push({ json: { email: 'decoy_' + rand() + '_' + (a.email.split('@')[0]) + '@honeypot.prism.local', password: 'H0ney!' + rand() + 'Pots', tag: 'decoy-for-' + a.email } });
      }
    }
  }
  return out.length ? out : [{ json: { email: 'none', password: 'none', tag: 'none' } }];
};
return run();

const items = $input.all();
const leakedAccounts = items.filter(i => i.json.leaked);
const total = items.reduce((s, i) => s + (i.json.breach_count || 0) + (i.json.paste_count || 0), 0);
return [{ json: { accounts_checked: items.length, leaked_accounts: leakedAccounts.length, leak_details: leakedAccounts.map(i => ({ email: i.json.email, breaches: i.json.breaches, pastes: i.json.pastes })), leaks_found: total } }];

const run = async () => {
  const items = $input.all();
  const bot2 = items.find(i => i.json.accounts_checked !== undefined) || { json: {} };
  const leaked = bot2.json.leak_details || [];
  const HIBP_KEY = $env.HIBP_API_KEY || '';
  const still = [];
  for (const l of leaked) {
    try {
      const res = await fetch('https://haveibeenpwned.com/api/v3/breachedaccount/' + encodeURIComponent(l.email), {
        headers: { 'hibp-api-key': HIBP_KEY, 'user-agent': 'prism-security-scanner/1.0' }
      });
      if (res.status === 200) {
        const b = await res.json();
        const names = (b || []).map(x => x.Name || x.Title);
        const fresh = names.filter(n => !(l.breaches || []).includes(n));
        if (fresh.length) still.push({ email: l.email, new_breaches: fresh });
      }
    } catch (e) {}
  }
  return [{ json: { leaks_persist: still.length, still_leaking: still } }];
};
return run();

const recheck = $input.first().json;
const bot1 = $('Bot 1 - Summarize').first().json;
const bot2 = $('Bot 2 - Summarize').first().json;
const runId = $('Security Agent - Start Run').first().json.run_id;
const status = recheck.leaks_persist > 0 ? 'LEAKS_PERSIST' : 'COMPLETED';
const report = JSON.stringify({ emails_scanned: bot1.emails_scanned || 0, emails_flagged: bot1.emails_flagged || 0, accounts_checked: bot2.accounts_checked || 0, leaks_found: bot2.leaks_found || 0, leaks_persist: recheck.leaks_persist || 0, still_leaking: recheck.still_leaking || [], finished_at: new Date().toISOString() });
return [{ json: { run_id: runId, status, emails_scanned: bot1.emails_scanned || 0, emails_flagged: bot1.emails_flagged || 0, accounts_checked: bot2.accounts_checked || 0, leaks_found: bot2.leaks_found || 0, leaks_persist: recheck.leaks_persist || 0, report } }];
